/* M.A.T — «Combate táctico»: tu soldado (el de «Crea tu soldado») contra 1–15 soldados IA de Rusia o de EE. UU., visto desde arriba.
   Datos: soldado.json (pesos medidos y fichas de fabricante), fichas del Armero 3D (alcance, cadencia, calibre) y,
   para el equipo ruso que no está en soldado.json, cifras publicadas con su fuente. El combate es un modelo
   simplificado y transparente de M.A.T (un juego, no una predicción) con semilla para repetirlo. */
const EN=()=>window.MAT_LANG==='en'; const L=(es,en)=>EN()?en:es; const LL=a=>Array.isArray(a)?(EN()?(a[1]||a[0]):a[0]):(a||'');
const VER=(document.querySelector('script[data-v]')||{getAttribute(){return '1';}}).getAttribute('data-v');
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const nf=(x,d)=>Number(x).toLocaleString(EN()?'en-GB':'es-ES',{minimumFractionDigits:d||0,maximumFractionDigits:d||0});
let DATA=null, ARM=null, ACTIVE=null;
function data(){ return DATA?Promise.resolve(DATA):fetch('soldado.json?v='+VER).then(r=>{ if(!r.ok) throw 0; return r.json(); }).then(d=>DATA=d); }
function arm(){ return ARM?Promise.resolve(ARM):import('./armero.js?v='+VER).then(m=>ARM=m); }
let REPLAY=null; function stopReplay(){ if(REPLAY){ try{ REPLAY.destroy(); }catch(e){} REPLAY=null; } }
function stop(){ stopReplay(); if(ACTIVE){ try{ ACTIVE.destroy(); }catch(e){} ACTIVE=null; } }
window.addEventListener('hashchange',()=>{ if(!/^#\/soldado\/combate/.test(location.hash)) stop(); });
/* ---- equipo ruso: cifras publicadas (no están en soldado.json) ---- */
const SRC={
  ratnik_en:['Wikipedia (en) — «Ratnik (program)»','https://en.wikipedia.org/wiki/Ratnik_(program)'],
  ratnik_ru:['Wikipedia (ru) — «Ратник (экипировка)»','https://ru.wikipedia.org/wiki/%D0%A0%D0%B0%D1%82%D0%BD%D0%B8%D0%BA_(%D1%8D%D0%BA%D0%B8%D0%BF%D0%B8%D1%80%D0%BE%D0%B2%D0%BA%D0%B0)'],
  atp:null };
const RU={ vest:{n:['Chaleco 6B45 (Ratnik) con placas','6B45 vest (Ratnik) with plates'],kg:7.5,cls:['clase 6 según GOST R 50744-95; para el fusil AK y el SVD (7,62×54R)','class 6 under GOST R 50744-95; rated against AK rifles and the SVD (7.62×54R)'],src:SRC.ratnik_en},
  helmet:{n:['Casco 6B47 (Ratnik)','6B47 helmet (Ratnik)'],kg:1.056,cls:['para pistola PM a 5 m y fragmentos a 630 m/s','against a PM pistol at 5 m and fragments at 630 m/s'],src:SRC.ratnik_ru},
  kit:{kg:17,n:['Equipo Ratnik básico: hasta 17 kg sin munición ni arma','Basic Ratnik kit: up to 17 kg without ammunition or weapon'],src:SRC.ratnik_ru} };
const FAC={ ru:{n:['Rusia','Russia'],flag:'🇷🇺',camo:'selva',camoN:['Selva (woodland) de M.A.T — el más parecido al EMR «Digital Flora» ruso (no hay patrón EMR en el Armero)','M.A.T woodland — the closest to Russia’s EMR “Digital Flora” (there is no EMR pattern in the Gunsmith)'],tracer:0x7dff6a},
  ins:{n:['Insurgentes','Insurgents'],flag:'',camo:'fde',camoN:['Ropa de paisano y prendas militares mezcladas, pañuelo (shemagh) y chaleco portacargadores; sin casco ni placas (bando genérico de M.A.T, sin grupos, banderas ni símbolos reales)','Mixed civilian and military clothes, shemagh headscarf and chest rig; no helmet or plates (a generic M.A.T side: no real groups, flags or symbols)'],tracer:0xffa040},
  us:{n:['EE. UU.','USA'],flag:'🇺🇸',camo:'arido',camoN:['Árido (multiterreno) de M.A.T — el más parecido al OCP/MARPAT (no hay patrón OCP en el Armero)','M.A.T arid multi-terrain — the closest to OCP/MARPAT (there is no OCP pattern in the Gunsmith)'],tracer:0xff4a2a} };
function loadSt(){ let s=null; try{ s=JSON.parse(localStorage.getItem('mat_soldado')||'null'); }catch(e){} return Object.assign({h:175,kg:80,role:null,lvl:0,q:{},arma:null,camo:'od'},s||{}); }
/* ---- números de las fichas ---- */
function firstM(t){ const m=String(t||'').replace(/\./g,'').match(/(\d[\d\s]*)\s*m\b/); return m?parseInt(m[1].replace(/\s/g,''),10):null; }
function optMag(a){ const x=ARM.ACC[a]; if(!x) return 1; if(x.dot) return 1; const s=(x.k?x.k[0]:'')+' '+x.n; const m=s.replace(',','.').match(/(\d+(?:\.\d+)?)\s*(?:[–-]\s*(\d+(?:\.\d+)?)\s*)?(?:×|x\b|aumentos)/i); return m?parseFloat(m[1]):1; }
function wInfo(b){ const M=ARM; if(!b) return null; const w=M.W.find(x=>x.id===b.id); if(!w) return null; const v=w.V[Math.min(b.v||0,w.V.length-1)]; const on={}; Object.entries(b.on||{}).forEach(([s,a])=>{ if(M.ACC[a]) on[s]=a; });
  const acc=Object.values(on).map(a=>M.ACC[a]); const addG=acc.filter(x=>x.slot!=='stock').reduce((s,x)=>s+(x.g||0),0); const md=M.fireModes?M.fireModes(w,v):{modes:['semi'],rate:null};
  const st=v.st||{}; const alc=firstM(st.alc&&st.alc[0]); const cal=st.cal?LL(st.cal):''; const opt=on.optic||null;
  return {w,v,on,kg:v.w!=null?v.w+addG/1000:null,alc,cal,rate:md.rate,modes:md.modes,mg:w.cat==='mg',opt,mag:opt?optMag(opt):1,dot:!!(opt&&M.ACC[opt].dot),optN:opt?M.ACC[opt].n:null,name:w.n+(w.V.length>1?' ('+LL(v.lab||v.id)+')':''),cad:st.cad?LL(st.cad):null,alcT:st.alc?LL(st.alc):null}; }
const RIFLE_PLATES=/^(sapi|esapi|p_hesco_3404|p_hesco_3612|p_ar500_heritage|p_hesco_4403mc|p_hesco_4601|p_hesco_rf3_400|p_velocity_psa4)$/;
function band(p){ const B=DATA.bands; for(const b of B){ if(b.max==null||p<=b.max) return b; } return B[B.length-1]; }
const MOVE=[1,1.25,1.5,1.8]; /* multiplicador del tiempo al cambiar de cobertura según la banda de carga (estimación de M.A.T) */
function profile(kind,st,fac){ const D=DATA; const P={kind,fac,st,body:st.kg||80,h:st.h||175,est:{}};
  P.wi=wInfo(st.arma);
  if(kind==='ins'){ P.gearKg=6; P.vestN=L('Chaleco portacargadores (chest rig), sin placas','Chest rig, no plates'); P.vestCls=L('no para munición de fusil','not rated against rifle rounds'); P.helmN=L('Sin casco: pañuelo (shemagh)','No helmet: shemagh headscarf'); P.helmCls=''; P.plate=false; P.plateN=0; P.side=false; P.helmet=false; P.est.kg=true; P.kgNote=L('estimación','estimate'); P.src=[]; }
  else if(kind==='ru'){ P.gearKg=RU.kit.kg; P.vestN=LL(RU.vest.n); P.vestCls=LL(RU.vest.cls); P.helmN=LL(RU.helmet.n); P.helmCls=LL(RU.helmet.cls); P.plate=true; P.plateN=2; P.side=false; P.helmet=true; P.est.kg=true; P.kgNote=L('sin munición (sin dato oficial)','without ammunition (no official figure)'); P.src=[RU.vest.src,RU.helmet.src]; }
  else { let g=0; Object.entries(st.q||{}).forEach(([id,q])=>{ const it=D.items[id]; if(it&&q) g+=it.g*q; }); P.gearKg=g/1000;
    const q=st.q||{}; const has=id=>(q[id]||0)>0; const plates=Object.keys(q).filter(id=>q[id]>0&&RIFLE_PLATES.test(id)); P.plateN=Math.min(2,(has('iba')?2:0)+plates.reduce((s,id)=>s+q[id],0)); P.plate=P.plateN>0; P.side=has('side')||has('p_esbi');
    const vest=Object.keys(q).find(id=>q[id]>0&&D.items[id]&&D.items[id].c==='vest'); const pl=plates[0]; P.vestN=[vest&&LL(D.items[vest].n),pl&&(LL(D.items[pl].n)+(q[pl]>1?' ×'+q[pl]:''))].filter(Boolean).join(' + ')||L('Sin chaleco ni placas','No vest or plates');
    P.vestCls=P.plate?L('placas para munición de fusil (ficha del fabricante o del Ejército)','plates rated for rifle rounds (maker or Army data)'):(has('p_soft_iiia_shellback_clc')?L('solo nivel IIIA (pistola): no para fusil','IIIA only (pistol): not for rifle rounds'):'');
    const hl=Object.keys(q).find(id=>q[id]>0&&D.items[id]&&D.items[id].c==='helmet'); P.helmet=!!hl; P.helmN=hl?LL(D.items[hl].n):L('Sin casco','No helmet'); P.helmCls=hl?L('para fragmentos y pistola; no para balas de fusil','against fragments and pistol rounds; not rifle rounds'):''; P.src=[]; }
  P.wKg=P.wi&&P.wi.kg!=null?P.wi.kg:0; P.tot=P.gearKg+P.wKg; P.pct=P.tot/P.body*100; const bi=DATA.bands.indexOf(band(P.pct)); P.band=band(P.pct); P.move=MOVE[Math.max(0,bi)]||1.8;
  P.prot=(P.plate?(P.plateN>=2?60:45):0)+(P.side?10:0)+(P.helmet?15:0); P.fire=P.wi?Math.round(Math.min(100,(P.wi.mg?55:30)+(P.wi.rate||300)/20)):0;
  return P; }
