function aiSt(fac,mg){ const D=DATA, M=ARM; const c=FAC[fac].camo;
  if(fac==='ins'){ const wid=mg?['pkm','pkp'].find(id=>M.W.some(x=>x.id===id)):['akm','ak47','ak74'].find(id=>M.W.some(x=>x.id===id)); const w=M.W.find(x=>x.id===wid)||M.W.find(x=>x.id==='ak74')||M.W.find(x=>x.id==='ak12'); return {h:174,kg:72,role:null,lvl:0,q:{uni:1,boots:1,iba:1},arma:{id:w.id,v:0,on:{}},camo:'od',ucamo:'fde',gcamo:'od',hcamo:'od',gl:'orig',pc:'molle',ins:1}; }
  if(fac==='us'){ const r=D.roles.find(x=>x.id===(mg?'ametrallador':'fusilero'))||D.roles.find(x=>x.id==='fusilero'); return {h:175,kg:80,role:r.id,lvl:0,q:Object.assign({},r.sel[0]),arma:JSON.parse(JSON.stringify(r.arma)),camo:'od',ucamo:c,gcamo:c,hcamo:c,gl:'tan',pc:'molle'}; }
  const wid=mg?['pkp','pkm'].find(id=>M.W.some(x=>x.id===id)):'ak12'; const w=M.W.find(x=>x.id===(wid||'ak12'))||M.W.find(x=>x.id==='ak12'); const v=w.V[0]; const ru=['pk120','1p87','1p63','kobra','obzor','p78','p29']; const opts=M.accs?M.accs(v,'optic'):[]; const opt=ru.find(a=>opts.includes(a));
  return {h:175,kg:80,role:null,lvl:0,q:{uni:1,boots:1,knee:1,gog:1,iba:1,ach:1},arma:{id:w.id,v:0,on:opt?{optic:opt}:{}},camo:'od',ucamo:c,gcamo:c,hcamo:c,gl:'negro',pc:'molle'}; }
/* ---- equipo de noche y granadas ---- */
function nightKit(P){ const st=P.st, q=st.q||{}, M=ARM; const on=(P.wi&&P.wi.on)||{}; const acc=Object.values(on).map(a=>M.ACC[a]).filter(Boolean); const txt=x=>(x.n+' '+(x.k?x.k.join(' '):'')).toLowerCase();
  const light=acc.some(x=>x.slot==='light'||/linterna|flashlight|lúmenes|lumens|\blm\b/.test(txt(x))); const laser=acc.find(x=>x.slot==='laser'); const ir=!!(laser&&/infrarroj|\bir\b|infrared/.test(txt(laser)));
  if(P.kind==='ru') return {nvg:false,nightSight:true,light:false,irLaser:false,frags:0,lightN:null,laserN:null};
  if(P.kind==='ins') return {nvg:false,nightSight:false,light:true,irLaser:false,frags:0,lightN:L('linterna','flashlight'),laserN:null};
  const nv=Object.keys(q).find(id=>q[id]>0&&/pvs|nvg|gpnvg/i.test(id)); return {nvg:!!nv,nvgN:nv&&DATA.items[nv]?LL(DATA.items[nv].n):null,nightSight:false,light,irLaser:ir,laserN:laser?laser.n:null,frags:q.frag||0}; }
function kit2d(P){ const wi=P.wi, nk=nightKit(P); let short=wi?wi.w.n:'—'; if(short.length>7) short=short.split(/\s+/).filter(s=>/\d/.test(s)).pop()||short.split(/\s+/).pop();
  const auto=wi&&(wi.modes||[]).some(m=>/auto|burst|ráfaga|rafaga/i.test(m)); const pistol=wi&&/pistol/.test(wi.w.cat||'');
  return Object.assign({short,wid:wi?wi.w.id:null,mg:!!(wi&&wi.mg),rate:(wi&&wi.rate)||600,auto:!!auto,alc:wi&&wi.alc,mag:wi?wi.mag:1,dot:wi&&wi.dot,plate:P.plate,plateN:P.plateN,move:P.move,magSize:wi&&wi.mg?100:pistol?15:30,reload:wi&&wi.mg?7:2.6},nk); }
