const WSND={m4a1:'m4',scar:'m4',sr25:'m4',ak12:'m4',mp7:'mp7',mp7a1:'mp7',m82:'m2',m82a1:'m2',m249:'m240',m240:'m240',pkm:'m240',pkp:'m240',g18c:'glock',glock:'glock'};
const AU={ctx:null,buf:{},voices:0,last:{}}; let SND_ON=(()=>{ try{ return localStorage.getItem('mat_combate_snd')!=='0'; }catch(e){ return true; } })();
function auInit(){ if(AU.ctx) { if(AU.ctx.state==='suspended') AU.ctx.resume().catch(()=>{}); return; } try{ const AC=window.AudioContext||window.webkitAudioContext; if(AC) AU.ctx=new AC(); }catch(e){} }
function auLoad(k){ if(!AU.ctx||!SND[k]||AU.buf[k]!==undefined) return; AU.buf[k]=0; fetch(SND[k].f).then(r=>r.arrayBuffer()).then(b=>new Promise((ok,ko)=>AU.ctx.decodeAudioData(b,ok,ko))).then(d=>{ AU.buf[k]=d; }).catch(()=>{ AU.buf[k]=null; }); }
function auPlay(k,vol,pan){ if(!SND_ON||!AU.ctx||!AU.buf[k]||AU.voices>14||vol<0.02) return; const C=AU.ctx, sl=SND[k].sl[Math.floor(Math.random()*SND[k].sl.length)]; try{ const s=C.createBufferSource(); s.buffer=AU.buf[k]; const g=C.createGain(); const t=C.currentTime; g.gain.setValueAtTime(vol,t); g.gain.setValueAtTime(vol,t+Math.max(0.02,sl[1]-0.04)); g.gain.linearRampToValueAtTime(0,t+sl[1]); s.connect(g); let out=g; if(C.createStereoPanner){ const p=C.createStereoPanner(); p.pan.value=Math.max(-0.9,Math.min(0.9,pan||0)); g.connect(p); out=p; } out.connect(C.destination); AU.voices++; s.onended=()=>{ AU.voices--; }; s.start(t,sl[0],sl[1]+0.01); }catch(e){} }
const DIFN={rec:['Recluta','Recruit'],vet:['Veterano','Veteran'],eli:['Élite','Elite']}, DIFD={rec:['Tarda más en apuntar, falla más y casi no se mueve: para aprender.','Slower to aim, misses more and barely moves: for learning.'],vet:['El equilibrio de siempre.','The usual balance.'],eli:['Apunta rápido, acierta mucho más y cambia de cobertura sin parar.','Aims fast, hits far more often and keeps changing cover.']};
const MISN={despejar:['Despejar','Clear'],rehen:['Rescatar al rehén','Rescue the hostage'],trinchera:['Tomar la trinchera','Take the trench'],carro:['Destruir carro de combate enemigo','Destroy the enemy tank'],heli:['Helicóptero derribado','Downed helicopter']}, MISD={heli:['Solo en Ciudad. Un helicóptero ha caído en el mercado: llega hasta él, asegura a los dos tripulantes, aguanta 35 s mientras las milicias convergen en 3 oleadas desde varias calles y después sal con la tripulación hasta el convoy. Inspirado en la batalla de Mogadiscio (3–4 de octubre de 1993, operación Gothic Serpent), en la que fueron derribados dos helicópteros MH-60 y una fuerza de rescate tuvo que abrirse paso por la ciudad; fuente: US Army Center of Military History, «The United States Army in Somalia, 1992–1994» (history.army.mil). Bandos genéricos: no representa a personas ni unidades reales.','City only. A helicopter has gone down in the market: reach it, secure the two crew, hold for 35 s while militia converge in 3 waves from several streets, then get the crew out to the convoy. Inspired by the Battle of Mogadishu (3–4 October 1993, Operation Gothic Serpent), when two MH-60 helicopters were shot down and a relief force had to fight its way through the city; source: US Army Center of Military History, “The United States Army in Somalia, 1992–1994” (history.army.mil). Generic sides: it does not depict real people or units.'],carro:['En Pueblo o en Montaña: un carro de combate enemigo vigila una calle, con infantería alrededor. Los fusiles no le hacen nada: solo el antitanque (3 cohetes contracarro de un solo uso, tipo C90) puede destruirlo. El lateral y la parte trasera son más débiles que el frontal. Gana si lo destruyes.','Village or Mountain: an enemy tank guards a street, with infantry around it. Rifles do nothing to it: only the AT gunner (3 single-shot anti-tank rockets, C90 type) can destroy it. The side and rear are weaker than the front. Win by destroying it.'],despejar:['Gana si dejas fuera de combate a todos los enemigos.','Win by taking every enemy out of action.'],rehen:['Hay un rehén (punto blanco) en una habitación con un guardia al lado. Gana si tu soldado llega hasta él; si el rehén muere (por una granada o por el apoyo), pierdes. Tu soldado no lanza granadas cerca del rehén, y el apoyo apunta lejos de él (aunque la dispersión puede alcanzarlo).','There is a hostage (white dot) in a room with a guard next to it. Win if your soldier reaches it; if the hostage dies (grenade or strike), you lose. Your soldier throws no grenades near the hostage, and any strike aims away from it (dispersion can still reach it).'],trinchera:['Solo en Trincheras: gana si mantienes el tramo central 6 segundos sin enemigos dentro (o si los abates a todos). Dos defensores empiezan dentro.','Trenches only: win by holding the central bay for 6 seconds with no enemy inside (or by taking them all down). Two defenders start inside.']};
function loadCfg(){ let c=null; try{ c=JSON.parse(localStorage.getItem('mat_combate_cfg')||'null'); }catch(e){} c=Object.assign({fac:'ru',n:6,map:'casa',night:false,air:'none',dif:'vet',mi:'despejar',eq:1},c||{}); if(![1,2,4,5].includes(+c.eq)) c.eq=1; c.eq=+c.eq; if(!FAC[c.fac]) c.fac='ru'; if(!MAPN[c.map]) c.map='casa'; if(!STRIKES[c.air]) c.air='none'; if(!DIFN[c.dif]) c.dif='vet'; if(!MISN[c.mi]) c.mi='despejar'; if(c.mi==='trinchera') c.map='trincheras'; if(c.mi==='carro'&&c.map!=='montana') c.map='pueblo'; if(c.mi==='heli') c.map='mogadiscio';  c.n=[1,2,3,4,5,6,10,15].includes(c.n|0)?(c.n|0):Math.max(1,Math.min(6,c.n|0||1)); c.sp=fixSp(c.sp,c.eq); if(!['r','1','0'].includes(c.tc)) c.tc='r'; return c; }
/* especialistas: una letra por miembro (tú primero): f fusilero, z zapador, a antitanque, m médico */
const SPEC={f:['Fusilero','Rifleman','🔫'],z:['Zapador','Breacher','💥'],a:['Antitanque','AT gunner','🚀'],m:['Médico','Medic','✚'],r:['Francotirador','Sniper','🎯']};
const SPDEF={1:'f',2:'fm',4:'fzma',5:'fzmar'};
function fixSp(sp,eq){ sp=String(sp||'').toLowerCase().replace(/[^fzamr]/g,''); if(sp.length!==eq) sp=(sp+SPDEF[eq].slice(sp.length)).slice(0,eq); return sp||SPDEF[eq]; }

/* ======== fase 4: plan de entrada (quién va a cada edificio) y equipo Fácil/Experto con consumibles reales ======== */
const PLAN_MAPS={casa:1,pueblo:1,mogadiscio:1,montana:1};
const GCOL=['#4aa3ff','#ffb020','#5ad16a','#ff6fae','#b48cff'];
const LET=i=>String.fromCharCode(65+i);
const BLDC={};
function bldInfo(map,KA){ if(BLDC[map]) return BLDC[map]; let r={M:null,b:[]}; try{ const s=C2.makeSim(map,KA,[KA,KA],{seed:1,team:2,spec:'ff',mission:'despejar'}); r={M:s.M,b:(s.blds||[]).map(b=>({i:b.i,lab:b.lab,x:b.x,y:b.y,w:b.w,h:b.h,nm:b.nm,rooms:b.rooms.map(ri=>s.M.rooms[ri])}))}; }catch(e){ console.warn('plan',e); } BLDC[map]=r; return r; }
function planOK(c){ return c.eq>1&&c.mi==='despejar'&&!!PLAN_MAPS[c.map]; }
function ordOf(t,nb){ const o=[]; String(t||'').toUpperCase().split('').forEach(ch=>{ const i=ch.charCodeAt(0)-65; if(i>=0&&i<nb&&!o.includes(i)) o.push(i); }); for(let i=0;i<nb;i++) if(!o.includes(i)) o.push(i); return o; }
function parsePl(s,eq,nb){ s=String(s||''); if(!nb) return null;
  if(s[0]==='j') return {mode:'j',ord:ordOf(s.slice(1),nb)};
  if(s[0]==='d'){ const pr=s.slice(1).split('.'); const a_=pr[0]||'', ord=ordOf(pr[1],nb); const as=[]; for(let i=0;i<eq;i++){ const ch=a_[i]||LET(ord[0]); if(ch==='w') as.push(-1); else { const k=ch.toUpperCase().charCodeAt(0)-65; as.push(k>=0&&k<nb?k:ord[0]); } } return {mode:'d',as,ord}; }
  return null; }
function encPl(p){ if(!p) return ''; const o=p.ord.map(LET).join(''); return p.mode==='j'?'j'+o:'d'+p.as.map(v=>v<0?'w':LET(v)).join('')+'.'+o; }
/* reparto por defecto al dividir: tú y el médico al primer edificio, el resto alternando, el francotirador (o el último con 4+ en una sola casa) vigila fuera */
function defSplit(sp,nb,ord){ const eq=sp.length; const as=new Array(eq).fill(ord[0]); let wt=sp.indexOf('r'); if(wt<1) wt=(nb===1||eq>=5)?eq-1:-1; if(eq<4&&nb>=2) wt=-1; if(eq===2&&nb===1) wt=1; if(wt>0) as[wt]=-1;
  if(nb>=2){ const clear=[...Array(eq).keys()].filter(i=>i!==wt); const n2=Math.max(1,Math.floor(clear.length/2)); const cand=clear.filter(i=>i>0&&sp[i]!=='m').sort((p,q)=>((sp[q]==='z'||sp[q]==='a')?1:0)-((sp[p]==='z'||sp[p]==='a')?1:0)); cand.slice(0,n2).forEach(i=>{ as[i]=ord[1]; }); }
  return {mode:'d',as,ord:ord.slice()}; }
function planGroups(p,sp){ /* igual que la simulación: grupos por edificio en el orden del plan, el tuyo primero */ const gs=[]; p.ord.forEach(bi=>{ const ids=[]; p.as.forEach((v,i)=>{ if(v===bi) ids.push(i); }); if(ids.length) gs.push({bi,ids}); }); gs.sort((a,b)=>(b.ids.includes(0)?1:0)-(a.ids.includes(0)?1:0)); return gs; }
